namespace PipelineForge.Core.Generation;

/// <summary>
/// Accepted-risk register: security/exceptions.yaml lists every accepted finding with an owner, a ticket and an
/// expiry. jenkins/scripts/exceptions.py checks it on every build and renders the scanners' ignore files from it,
/// so suppressions cannot be added without those fields and cannot outlive their expiry.
/// </summary>
public static class ExceptionsWriter
{
    public const int MaxDays = 180;

    public static string Register(GenerationContext ctx) => $"""
        # Accepted security risks for {ctx.Config.Name}. Generated by PipelineForge; maintained by the team.
        # Every build renders the scanners' ignore files from this list and fails when an entry has expired,
        # has no owner or ticket, or expires more than {MaxDays} days ahead. Protect this file with CODEOWNERS.
        #
        # scanner: trivy | dependency-check | snyk  -> vulnerability id (CVE-..., GHSA-..., SNYK-...)
        #          gitleaks                          -> finding fingerprint from the report
        #          zap                               -> ZAP rule id (e.g. 10038)
        #
        # exceptions:
        #   - id: CVE-2024-12345
        #     scanner: trivy
        #     reason: Not reachable; the vulnerable parser is never called.
        #     owner: team-{ctx.Config.Name}
        #     ticket: SEC-123
        #     expires: 2026-12-31
        exceptions: []

        """;

    public const string Script = """
        #!/usr/bin/env python3
        # Accepted-risk register. Generated by PipelineForge.
        # Checks security/exceptions.yaml and renders the scanners' ignore files from it. Exits 1 when an entry
        # has expired, misses an owner or ticket, expires more than MAX_DAYS ahead, or is malformed.
        # Usage: exceptions.py security/exceptions.yaml [--today YYYY-MM-DD] [--out DIR]
        import datetime
        import json
        import os
        import re
        import sys
        from xml.sax.saxutils import escape

        MAX_DAYS = 180
        WARN_DAYS = 14
        FIELDS = ("id", "scanner", "reason", "owner", "ticket", "expires")
        VULN_ID = r"^[A-Za-z0-9][A-Za-z0-9._:-]{1,99}$"
        ID_RX = {
            "trivy": VULN_ID,
            "dependency-check": VULN_ID,
            "snyk": VULN_ID,
            "gitleaks": r"^[A-Za-z0-9._/:@-]{1,300}$",
            "zap": r"^[0-9]{1,6}$",
        }
        OWNER_RX = r"^[A-Za-z0-9 ._@-]{1,80}$"
        TICKET_RX = r"^[A-Za-z0-9._#/:-]{1,80}$"


        def strip_comment(line):
            quote = None
            for i, ch in enumerate(line):
                if quote:
                    if ch == quote:
                        quote = None
                elif ch in "'\"":
                    quote = ch
                elif ch == "#" and (i == 0 or line[i - 1] in " \t"):
                    return line[:i]
            return line


        def unquote(value):
            if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
                inner = value[1:-1]
                return inner.replace("''", "'") if value[0] == "'" else inner
            return value


        def parse(text):
            # A small YAML subset: "exceptions:" followed by a list of flat mappings with scalar values.
            entries, current, root = [], None, None
            for no, raw in enumerate(text.splitlines(), 1):
                line = strip_comment(raw).rstrip()
                if not line.strip():
                    continue
                if root is None:
                    if line.strip() in ("exceptions:", "exceptions: []"):
                        root = line.strip()
                        continue
                    raise ValueError(f"line {no}: expected 'exceptions:'")
                if root == "exceptions: []":
                    raise ValueError(f"line {no}: replace 'exceptions: []' with 'exceptions:' before adding entries")
                item = line.lstrip()
                if item.startswith("- "):
                    current = {"_line": no}
                    entries.append(current)
                    item = item[2:].lstrip()
                elif current is None:
                    raise ValueError(f"line {no}: expected a list item such as '- id: CVE-...'")
                key, sep, value = item.partition(":")
                key = key.strip()
                if not sep or key not in FIELDS:
                    raise ValueError(f"line {no}: expected one of {', '.join(FIELDS)}")
                if key in current:
                    raise ValueError(f"line {no}: '{key}' appears twice in one entry")
                current[key] = unquote(value.strip())
            return entries


        def check(entries, today):
            problems, warnings, seen = [], [], set()
            for e in entries:
                where = f"entry at line {e['_line']}"
                missing = [f for f in FIELDS if not e.get(f)]
                if missing:
                    problems.append(f"{where}: missing {', '.join(missing)}")
                    continue
                scanner = e["scanner"]
                if scanner not in ID_RX:
                    problems.append(f"{where}: unknown scanner '{scanner}' (use {', '.join(sorted(ID_RX))})")
                    continue
                if not re.match(ID_RX[scanner], e["id"]):
                    problems.append(f"{where}: '{e['id']}' is not a valid {scanner} id")
                if (scanner, e["id"]) in seen:
                    problems.append(f"{where}: {scanner} {e['id']} is listed twice")
                seen.add((scanner, e["id"]))
                if not re.match(OWNER_RX, e["owner"]):
                    problems.append(f"{where}: owner must be a team or person name")
                if not re.match(TICKET_RX, e["ticket"]):
                    problems.append(f"{where}: ticket must be an issue key or URL path")
                if len(e["reason"]) > 300 or any(ord(c) < 32 for c in e["reason"]):
                    problems.append(f"{where}: reason must be one line of at most 300 characters")
                try:
                    expires = datetime.date.fromisoformat(e["expires"])
                except ValueError:
                    problems.append(f"{where}: expires must be a date such as 2026-12-31")
                    continue
                if expires < today:
                    problems.append(f"{where}: {scanner} {e['id']} expired on {expires}; fix it or renew it with a new review")
                elif expires > today + datetime.timedelta(days=MAX_DAYS):
                    problems.append(f"{where}: expires more than {MAX_DAYS} days ahead; review accepted risks at least twice a year")
                elif expires <= today + datetime.timedelta(days=WARN_DAYS):
                    warnings.append(f"{scanner} {e['id']} expires on {expires} (owner {e['owner']}, {e['ticket']})")
            return problems, warnings


        def write(out, path, text):
            target = os.path.join(out, path)
            os.makedirs(os.path.dirname(target) or ".", exist_ok=True)
            with open(target, "w", encoding="utf-8") as f:
                f.write(text)


        def render(entries, out):
            by = lambda s: [e for e in entries if e["scanner"] == s]
            note = lambda e: f"{e['reason']} (owner {e['owner']}, {e['ticket']})"
            header = "# Generated from security/exceptions.yaml on every build. Do not edit.\n"

            write(out, "security/.trivyignore", header + "".join(
                f"# {note(e)}\n{e['id']} exp:{e['expires']}\n" for e in by("trivy")))
            write(out, ".gitleaksignore", header + "".join(f"{e['id']}\n" for e in by("gitleaks")))

            suppressions = "".join(
                f"  <suppress until=\"{e['expires']}Z\">\n"
                f"    <notes>{escape(note(e))}</notes>\n"
                + (f"    <cve>{escape(e['id'])}</cve>\n" if e["id"].startswith("CVE-")
                   else f"    <vulnerabilityName>{escape(e['id'])}</vulnerabilityName>\n")
                + "  </suppress>\n"
                for e in by("dependency-check"))
            write(out, "security/dependency-check-suppressions.xml",
                  "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!-- Generated from security/exceptions.yaml. -->\n"
                  "<suppressions xmlns=\"https://jeremylong.github.io/DependencyCheck/dependency-suppression.1.3.xsd\">\n"
                  + suppressions + "</suppressions>\n")

            policy = {"version": "v1.25.0", "patch": {}, "ignore": {
                e["id"]: [{"*": {"reason": note(e), "expires": f"{e['expires']}T00:00:00.000Z"}}] for e in by("snyk")}}
            write(out, ".snyk", "# Generated from security/exceptions.yaml.\n" + json.dumps(policy, indent=2) + "\n")

            # ZAP: keep the generated rule levels and set the accepted rules to IGNORE.
            rules_path = os.path.join(out, "security/zap-rules.tsv")
            lines = open(rules_path, encoding="utf-8").read().splitlines() if os.path.exists(rules_path) else []
            ignored = {e["id"]: e for e in by("zap")}
            merged = [l for l in lines if l.split("\t", 1)[0] not in ignored]
            merged += [f"{rule}\tIGNORE\t({e['ticket']}, until {e['expires']})" for rule, e in ignored.items()]
            write(out, "security/zap-rules.tsv", "\n".join(merged) + "\n")

            table = "".join(
                f"| {e['scanner']} | `{e['id']}` | {e['owner']} | {e['ticket']} | {e['expires']} | {e['reason'].replace('|', '/')} |\n"
                for e in sorted(entries, key=lambda e: e["expires"]))
            write(out, "reports/exceptions.md", "# Accepted risks\n\n| Scanner | Id | Owner | Ticket | Expires | Reason |\n|---|---|---|---|---|---|\n" + table)


        def main(argv):
            if not argv:
                print("usage: exceptions.py security/exceptions.yaml [--today YYYY-MM-DD] [--out DIR]", file=sys.stderr)
                return 2
            register, today, out = argv[0], datetime.datetime.now(datetime.timezone.utc).date(), "."
            rest = argv[1:]
            while rest:
                flag, value, rest = rest[0], rest[1] if len(rest) > 1 else "", rest[2:]
                if flag == "--today":
                    today = datetime.date.fromisoformat(value)
                elif flag == "--out":
                    out = value
                else:
                    print(f"unknown option {flag}", file=sys.stderr)
                    return 2
            try:
                with open(register, encoding="utf-8") as f:
                    entries = parse(f.read())
            except (OSError, ValueError) as err:
                print(f"{register}: {err}", file=sys.stderr)
                return 1
            problems, warnings = check(entries, today)
            for w in warnings:
                print(f"WARNING: {w}")
            if problems:
                for p in problems:
                    print(f"{register}: {p}", file=sys.stderr)
                return 1
            render(entries, out)
            print(f"{len(entries)} accepted risk(s); ignore files rendered.")
            return 0


        if __name__ == "__main__":
            sys.exit(main(sys.argv[1:]))

        """;
}
